{"operationName":"getData","variables":{"offset":0,"limit":20},"query":"query getData($offset: Int!, $limit: Int!) {
  artworks_aggregate(
    where: {status: {_neq: "1"}, deleted_at: {_is_null: true}}
    order_by: {id: desc}
  ) {
    aggregate {
      count
      __typename
    }
    __typename
  }
  artworks(
    offset: $offset
    limit: $limit
    where: {status: {_neq: "1"}, deleted_at: {_is_null: true}}
    order_by: {id: desc}
  ) {
    id
    url
    thumbnail
    name
    width
    height
    design_format
    updated_at
    is_published_by_campaigns: campaign_artwork_printareas(
      where: {deleted_at: {_is_null: true}, campaign: {campaign_instances: {instance: {deleted_at: {_is_null: true}, visible: {_eq: true}}}}}
      limit: 1
    ) {
      id
      __typename
    }
    is_used_by_campaigns: campaign_artwork_printareas(
      where: {deleted_at: {_is_null: true}}
      limit: 1
    ) {
      id
      __typename
    }
    is_published_by_platform_products: platform_artworks(
      where: {platform_product: {published_at: {_is_null: false}}}
      limit: 1
    ) {
      id
      __typename
    }
    is_used_by_platform_products: platform_artworks(limit: 1) {
      id
      __typename
    }
    status
    staff {
      id
      name
      email
      __typename
    }
    staff_id
    __typename
  }
}"}
